DEST = Path("_site/kanto-journey/assets")

def build_sprite(item):
    filename, expected = item
    number, facing = filename[:-4].split("-")
    if not (1 <= int(number) <= 151 and facing in ("front", "back")):
        raise ValueError("Unexpected sprite " + filename)
    suffix = f"back/{number}.png" if facing == "back" else f"{number}.png"
    url = f"https://raw.githubusercontent.com/PokeAPI/sprites/{PIN}/sprites/pokemon/{suffix}"
    for attempt in range(4):
        try:
            req = Request(url, headers={"User-Agent": "KantoJourneyPagesBuild"})
            with urlopen(req, timeout=30) as response:
                binary = response.read()
            actual = sha1(b"blob " + str(len(binary)).encode("ascii") + bytes([0]) + binary).hexdigest()
            if actual != expected:
                raise ValueError(f"Checksum mismatch: {filename} {actual} != {expected}")
            (DEST / filename).write_bytes(binary)
            return filename
        except (URLError, OSError) as exc:
            if attempt == 3:
                raise RuntimeError(f"Could not download {filename}") from exc
            sleep(1.5 * (attempt + 1))

def main():
    if len(EXPECTED) != 302:
        raise AssertionError("Expected 302 Kanto sprite assets")
    DEST.mkdir(parents=True, exist_ok=True)
    with ThreadPoolExecutor(max_workers=12) as pool:
        for future in as_completed([pool.submit(build_sprite, item) for item in EXPECTED.items()]):
            future.result()
    if len(list(DEST.glob("*.png"))) != 302:
        raise AssertionError("Incomplete sprite set")
    print("Kanto Journey: 302 sprite files verified")

if __name__ == "__main__":
    main()
